\n    let order = matches.[0]\\n\\n    let target =\\n        if isStatus request.toStatus \\\"processing\\\" then\\n            Some \\\"processing\\\"\\n        elif isStatus request.toStatus \\\"cancelled\\\" then\\n            Some \\\"cancelled\\\"\\n        elif isStatus request.toStatus \\\"completed\\\" then\\n            Some \\\"completed\\\"\\n        else\\n            None\\n\\n    let valid =\\n        match target with\\n        | Some status ->\\n            (isStatus order.status \\\"pending\\\"\\n             && (status = \\\"processing\\\" || status = \\\"cancelled\\\"))\\n            || (isStatus order.status \\\"processing\\\"\\n                && (status = \\\"completed\\\" || status = \\\"cancelled\\\"))\\n        | None -> false\\n\\n    if not valid then\\n        raise (InvalidOperationException(\\\"invalid transition\\\"))\\n\\n    { id = order.id\\n      status = target.Value }\\n\\nlet idsResponse (orders: Order array) =\\n    orders\\n    |> Array.map (fun order -> order.id)\\n    |> fun ids -> JsonSerializer.Serialize({ ids = ids }, options)\\n\\nlet handle (request: Request) =\\n    let orders = normalizeOrders request.orders\\n\\n    match request.operation with\\n    | operation when isStatus operation \\\"ready\\\" ->\\n        ready orders |> idsResponse\\n    | operation when isStatus operation \\\"overdue\\\" ->\\n        if not request.asOf.HasValue then\\n            raise (InvalidOperationException(\\\"asOf is required for overdue\\\"))\\n\\n        overdue request.asOf.Value orders |> idsResponse\\n    | operation when isStatus operation \\\"atRisk\\\" ->\\n        if not request.asOf.HasValue then\\n            raise (InvalidOperationException(\\\"asOf is required for atRisk\\\"))\\n\\n        atRisk request.asOf.Value orders |> idsResponse\\n    | operation when isStatus operation \\\"vipReady\\\" ->\\n        orders\\n        |> ready\\n        |> Array.filter isVip\\n        |> idsResponse\\n    | operation when isStatus